css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .82); display: flex; justify-content: space-between; padding: 8% 7%; border-radius: 5px; background: linear-gradient(#334155, #0b1220); box-shadow: inset 0 0 0 2px #475569; }
.loader span { position: relative; width: 11%; border-radius: 999px; background: rgba(255, 255, 255, .12); }
.loader span::before { content: ''; position: absolute; top: -7%; left: 8%; width: 84%; height: 5%; border-radius: 999px; background: var(--accent-2); animation: led calc(var(--loader-speed) * 1.1) steps(2, end) infinite; }
.loader span::after { content: ''; position: absolute; left: -32%; width: 164%; height: 15%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 34%, var(--accent)), var(--accent)); box-shadow: 0 2px 4px rgba(0, 0, 0, .45); animation: fade-move calc(var(--loader-speed) * 2.2) ease-in-out infinite; }
.loader span:nth-child(2)::after { animation-delay: calc(var(--loader-speed) * .18); }
.loader span:nth-child(2)::before { animation-delay: calc(var(--loader-speed) * .18); }
.loader span:nth-child(3)::after { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(3)::before { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(4)::after { animation-delay: calc(var(--loader-speed) * .54); }
.loader span:nth-child(4)::before { animation-delay: calc(var(--loader-speed) * .54); }
.loader span:nth-child(5)::after { animation-delay: calc(var(--loader-speed) * .72); }
.loader span:nth-child(5)::before { animation-delay: calc(var(--loader-speed) * .72); }
@keyframes fade-move { 0%, 100% { top: 6%; } 50% { top: 78%; } }
@keyframes led { 0%, 100% { opacity: .28; } 50% { opacity: 1; } }
